	@Test
	void publicationFailureStopsLaterDeltasAndSurfacesGap(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		Path live = directory.resolve("live");
		LmdbStore store = new LmdbStore(live.toFile(), new LmdbStoreConfig().setBackupJournalEnabled(true));
		store.init();
		BackupResult full;
		long first;
		long target;
		try {
			full = store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			long acknowledged = publisher.acknowledgedTransactionId();
			Files.deleteIfExists(backups.resolve("txlog"));
			Files.writeString(backups.resolve("txlog"), "blocked");
			add(store, statement("first", "one"));
			first = store.getBackingStore().getCurrentCommittedTxnId();
			assertThrows(SailException.class, () -> store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(full.getEndTransactionId())
							.build()));
			assertEquals(acknowledged, publisher.acknowledgedTransactionId());
			assertEquals(List.of(first), store.getBackingStore()
					.getTripleStore()
					.listBackupStageTransactions(full.getEndTransactionId(), Long.MAX_VALUE));
			// The first archive write has failed before this later native commit becomes visible.
			add(store, statement("second", "two"));
			target = store.getBackingStore().getCurrentCommittedTxnId();
			SailException failure = assertThrows(SailException.class, () -> store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(full.getEndTransactionId())
							.build()));
			assertTrue(failure.getMessage().contains("Missing committed transaction journal at"));
			assertTrue(store.getBackupService().getStatus().getLastFailureMessage().isPresent());
			assertEquals(acknowledged, publisher.acknowledgedTransactionId(),
					"Later native commits must not acknowledge across a failed archive write");
			assertEquals(List.of(first, target), store.getBackingStore()
					.getTripleStore()
					.listBackupStageTransactions(full.getEndTransactionId(), Long.MAX_VALUE));
		} finally {
			store.shutDown();
		}
		Files.delete(backups.resolve("txlog"));
		LmdbStore reopened = new LmdbStore(live.toFile(), new LmdbStoreConfig().setBackupJournalEnabled(true));
		reopened.init();
		try {
			assertEquals(target, reopened.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(full.getEndTransactionId())
							.build())
					.getEndTransactionId());
			assertEquals(List.of(first, target),
					publishedTransactions(reopened, backups, full.getEndTransactionId(), target));
			try (SailConnection connection = reopened.getConnection()) {
				assertEquals(2L, connection.size());
			}
		} finally {
			reopened.shutDown();
		}
		// A second reopen must not attempt to republish acknowledged records or lose its baseline.
		LmdbStore again = new LmdbStore(live.toFile(), new LmdbStoreConfig().setBackupJournalEnabled(true));
		again.init();
		try {
			assertEquals(target, again.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(full.getEndTransactionId())
							.build())
					.getEndTransactionId());
		} finally {
			again.shutDown();
		}
	}

	@Test
	void shutdownDrainsPublisherBeforeClosingService(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile(),
				new LmdbStoreConfig().setBackupJournalEnabled(true));
		store.init();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		ExecutorService task = Executors.newSingleThreadExecutor();
		try {
			store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			store.getBackingStore().backupPublisher().setBeforePublication(() -> {
				entered.countDown();
				await(release);
			});
			add(store, statement("shutdown", "durable"));
			long target = store.getBackingStore().getCurrentCommittedTxnId();
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			// This transaction cannot join the first batch, whose durability boundary is already fixed.
			add(store, statement("late-shutdown", "also-durable"));
			long later = store.getBackingStore().getCurrentCommittedTxnId();
			LmdbBackupServiceImpl service = (LmdbBackupServiceImpl) store.getBackupService();
			AtomicReference<Thread> shutdownThread = new AtomicReference<>();
			var shutdown = task.submit(() -> {
				shutdownThread.set(Thread.currentThread());
				store.shutDown();
			});
			awaitPublisherShutdown(shutdownThread);
			release.countDown();
			shutdown.get(10, TimeUnit.SECONDS);
			assertEquals(List.of(target, later), service.publishedTransactionIds(backups, target - 1, later),
					"A later batch must finish even after map-growth admission has closed for shutdown");
		} finally {
			release.countDown();
			task.shutdownNow();
			assertTrue(task.awaitTermination(10, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

	private static void awaitPublisherShutdown(AtomicReference<Thread> reference) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (System.nanoTime() < deadline) {
			Thread thread = reference.get();
			if (thread != null) {
				for (StackTraceElement frame : thread.getStackTrace()) {
					if (frame.getClassName().equals(PostCommitBackupPublisher.class.getName())
							&& frame.getMethodName().equals("close")) {
						return;
					}
				}
			}
			Thread.yield();
		}
		throw new AssertionError("Store shutdown must reach its publisher drain before publication is released");
	}

	private static List<Long> publishedTransactions(LmdbStore store, Path backups, long from, long to)
			throws IOException {
		return ((LmdbBackupServiceImpl) store.getBackupService()).publishedTransactionIds(backups, from, to);
	}

	private static Path exportedLog(LmdbStore store, Path backups, long transaction) throws IOException {
		Path exports = Files.createTempDirectory(backups.getParent(), "exported-journal-");
		((LmdbBackupServiceImpl) store.getBackupService()).exportTransactionLogs(backups, transaction - 1,
				transaction, exports);
		return exports.resolve(logName(transaction));
	}

	private static String logName(long transaction) {
		return String.format("txn-%020d.delta.gz", transaction);
	}

	private static Statement statement(String subject, String label) {
		var vf = SimpleValueFactory.getInstance();
		return vf.createStatement(vf.createIRI("urn:" + subject), RDF.TYPE, vf.createLiteral(label));
	}

	private static void add(LmdbStore store, Statement statement) {
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			connection.commit();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(20, TimeUnit.SECONDS)) {
				throw new AssertionError("Publication release was not signalled");
			}
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

